1	import { spawnSync } from 'node:child_process';
2	import { readFileSync, writeFileSync, existsSync, statSync } from 'node:fs';
3	import { join, resolve, sep } from 'node:path';
4	import { parseEntries, sessionTranscriptPaths } from './session-transcript.mjs';
5	import { SHARED_SUBDIR, packEntryId } from '../../pack_loader/pack-registry.mjs';
6	import { canonicalPackVersions } from '../../pack_loader/renamed-packs.mjs';
7	import { SETTINGS_FILE, LEGACY_SETTINGS_FILE, settingsPath } from '../../settings-file.mjs';
8	import { isVersion } from '../../version.mjs';
9	
10	function sh(root, cmd, args, { allowFail = false, input = undefined, timeout = undefined } = {}) {
11	  const r = spawnSync(cmd, args, { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, input, timeout });
12	  if (r.status !== 0 && !allowFail) {
13	    throw new Error(`${cmd} ${args.join(' ')} failed (${r.status}): ${r.stderr}`);
14	  }
15	  return r.status === 0 ? r.stdout : null;
16	}
17	
18	const git = (root, ...args) => sh(root, 'git', args);
19	const gitTry = (root, ...args) => sh(root, 'git', args, { allowFail: true });
20	
21	// The base branch this repo's work is judged against, in preference order.
22	// Exported because the CI entry point (../ci-work-scope.mjs) fetches these same
23	// refs before a context is built at all — one list, so what CI fetches and what a
24	// context resolves can never name different branches.
25	export const BASE_REF_CANDIDATES = ['origin/main', 'origin/master', 'main', 'master'];
26	
27	function resolveBaseRef(root) {
28	  for (const ref of BASE_REF_CANDIDATES) {
29	    if (gitTry(root, 'rev-parse', '--verify', '--quiet', `${ref}^{commit}`) !== null) return ref;
30	  }
31	  return null;
32	}
33	
34	const FETCH_TIMEOUT_MS = 8000;
35	const FETCH_WINDOW_MS = 5 * 60_000;
36	
37	// A remote-tracking base ref is only as fresh as the last fetch, and a cloud session's
38	// clone freezes it at container-creation time — so every commit the base branch gained
39	// since lands inside `mergeBase..HEAD` and gets billed to the work. That is a wrong
40	// verdict, not a stale one: the delta rules (squash-merge-history above all, a *blocking*
41	// rule) report other people's commits as introduced by this change, and `--changed`
42	// widens to files the change never touched. Refreshing the ref once per run is what makes
43	// "the work" mean the work.
44	//
45	// Best-effort by construction — no network, no remote, a lock held, a slow server: the
46	// fetch fails or times out and the run continues against the ref as it stands, exactly as
47	// before this existed. It writes ONLY the remote-tracking ref (explicit refspec, no tags):
48	// no local branch, no index, no working tree, nothing the session could be surprised by.
49	// Set CLAUDINITE_CHECKS_NO_FETCH=1 to skip it (sealed sandboxes, or to pin a base).
50	//
51	// And it runs once per freshness window, not once per run: the Stop hook builds a context
52	// every turn with tracked changes, and the fetch is that path's dominant wall-clock cost
53	// (~0.7s healthy, 8s timeout when the network is not). A marker in the git dir records
54	// which ref was refreshed and when; a run inside the window trusts it and skips. The
55	// marker is PER-REF on purpose — a fetch of some other ref (or a marker left by one) says
56	// nothing about this base's freshness — and the staleness the window admits is the same
57	// class the fetch's own failure tolerance already accepts, now bounded by the window.
58	function refreshBaseRef(root, ref) {
59	  if (!ref || process.env.CLAUDINITE_CHECKS_NO_FETCH === '1') return;
60	  const m = /^([^/]+)\/(.+)$/.exec(ref);
61	  if (!m) return; // a local branch is already as current as the checkout — nothing to fetch
62	  const markerRel = (gitTry(root, 'rev-parse', '--git-path', 'claudinite-base-refresh.json') || '').trim();
63	  const marker = markerRel ? resolve(root, markerRel) : null;
64	  if (marker) {
65	    try {
66	      const last = JSON.parse(readFileSync(marker, 'utf8'));
67	      if (last.ref === ref && Date.now() - last.at < FETCH_WINDOW_MS) return;
68	    } catch { /* no marker (or an unreadable one) means no known freshness — fetch */ }
69	  }
70	  const [, remote, branch] = m;
71	  const fetched = sh(root, 'git', ['fetch', '--quiet', '--no-tags', remote,
72	    `+refs/heads/${branch}:refs/remotes/${remote}/${branch}`],
73	  { allowFail: true, timeout: FETCH_TIMEOUT_MS });
74	  if (fetched !== null && marker) {
75	    try { writeFileSync(marker, JSON.stringify({ ref, at: Date.now() })); }
76	    catch { /* an unwritable git dir only costs the next run a fetch */ }
77	  }
78	}
79	
80	function lines(out) {
81	  return (out || '').split('\n').filter(Boolean);
82	}
83	
84	// Files git marks vendored or generated (linguist-vendored / linguist-generated in
85	// .gitattributes) — third-party or machine-written content, not the project's own
86	// code. `buildContext` drops these from the default `ctx.files`, so every check that
87	// reasons about "the project's code" skips them for free: a suppression marker inside
88	// a recorded fixture, a placement "violation" in a generated artifact, and a dangling
89	// link in a vendored doc are none of them the project's decision. `git check-attr`
90	// honors .gitattributes patterns/precedence natively (paths on stdin so a large repo
91	// can't overflow the arg list). The unfiltered set stays on `ctx.allFiles` for the one
92	// check that reasons *about* generated files (generated-merge-driver).
93	function vendoredSet(root, files) {
94	  const set = new Set();
95	  if (!files.length) return set;
96	  const out = sh(root, 'git', ['check-attr', '--stdin', 'linguist-vendored', 'linguist-generated'],
97	    { allowFail: true, input: files.join('\n') + '\n' });
98	  for (const line of (out || '').split('\n')) {
99	    const m = /^(.*): (?:linguist-vendored|linguist-generated): (.*)$/.exec(line);
100	    if (m && m[2] === 'set') set.add(m[1]);
101	  }
102	  return set;
103	}
104	
105	// The complete set of top-level settings the settings file may carry. A key
106	// outside this set is a typo or a stale name — a settings error as real as invalid
107	// JSON, caught at load so it can't silently change nothing. `packConfig` is the
108	// legacy home of per-pack parameters — still honored while the fleet migrates to
109	// pack-entry `config` (the converge folds it in), no longer documented. The
110	// `pack-entry-config` baseline migration (engine/migrations/) documents the fold; the
111	// key and the overlay below come out on #1640's window, after which a straggler gets
112	// the unknown-setting error.
113	// `engineVersion` is the engine version this repo's mount holds, written by the
114	// update flows; a pack's installed version sits on that pack's own entry. Both were
115	// a nested `claudinite` block until #1252, alongside an `updated` datetime and a
116	// `ref` — those two held the provenance of the last FULL re-vendor rather than of
117	// this mount, so a member converging nightly read as months stale, and nothing may
118	// judge freshness by them any more because they no longer exist.
119	// `dailyClaudiniteUpdatesRequirePrReview` is the harsh override: true leaves this
120	// repo's daily update PR open for a human. Absent — the normal shape — means it
121	// lands on its own. It is an override rather than a materialized preference
122	// because every member wants the same thing, and the one that doesn't should have
123	// to say so (#1252).
124	// `taskScheduler` is the per-repo maintenance anchor the vendored hourly scheduler
125	// reads (per-project-scheduling DESIGN §2) — { dailyHour, weeklyDay, monthlyDay },
126	// all UTC. Absence means the documented defaults, so an omitted key is not an
127	// error; a present one is range-validated at load below. Its declaration is also
128	// the per-repo cutover marker during the scheduling rollout (MIGRATION Phase 0.6).
129	// Nothing writes into a member's README any more, so there is no `badges` key here:
130	// a member carrying the stale one gets the unknown-setting error below, and the
131	// wiring converge clears it.
132	// `dormant` is the project's own declaration that it is out of the RECURRING work —
133	// see isDormant below for exactly how much that covers.
134	// `claudinite` and `maintenance` are the two retired blocks, tolerated on read so a
135	// member that has not yet run the #1252 record still loads. LEGACY_CONFIG_KEYS is
136	// what Phase 3 deletes.
137	export const CONFIG_KEYS = ['packs', 'rules', 'accept', 'sharedConstants', 'packConfig',
138	  'engineVersion', 'dailyClaudiniteUpdatesRequirePrReview', 'taskScheduler', 'dormant'];
139	
140	// The retired blocks, read but never written. Their content is folded into the
141	// current shape by the load below, so nothing downstream sees either name.
142	// @legacy-tolerance advisory:legacy-shape-in-use retire:#1640
143	export const LEGACY_CONFIG_KEYS = ['claudinite', 'maintenance'];
144	const KNOWN_CONFIG_KEYS = [...CONFIG_KEYS, ...LEGACY_CONFIG_KEYS];
145	
146	// Does this project declare itself DORMANT? A project goes dormant when it is
147	// finished, parked, or simply not being worked on: it should stop paying the
148	// upkeep of a project that IS being worked on.
149	//
150	// What dormancy means, exactly — it is narrow on purpose:
151	//   - NO RECURRING WORK. The vendored scheduler stops before it evaluates
152	//     anything before it evaluates a precondition, so no work item is instantiated,
153	//     no agent session is started, and no maintenance PR is opened.
154	//     Nothing scheduled runs "for nothing" on a repo nobody is working on.
155	//   - NO FLEET CEREMONY. Whatever looks at this repo from the OUTSIDE reads the
156	//     same declaration and leaves it alone rather than reporting it as unhealthy —
157	//     a repo TOLD to stop keeping up must not then be nagged for not keeping up.
158	//     Which is why this predicate is exported for a raw declaration too (below).
159	//   - EVERYTHING ELSE STAYS ON. Claudinite is not switched off: the session
160	//     hooks, the checks engine, the mounted skills and pack prose all work
161	//     exactly as before the moment someone opens a session on the repo. Dormancy
162	//     is about unattended upkeep, never about what an interactive session may do.
163	//
164	// The predicate reads BOTH shapes deliberately: a raw parsed .claudinite-settings.json
165	// and the normalized config loadConfig returns. A cross-repo reader fetches another
166	// repo's declaration over the API with no engine loaded against that tree, and it
167	// must decide dormancy by the same test that repo's own scheduler used — a second
168	// notion of dormancy would nag exactly the repos that had already opted out. One
169	// definition, both sides.
170	export const isDormant = (config) => config?.dormant === true;
171	
172	// The keys a `schedule` object may carry, and the canonical weekday vocabulary
173	// (mirrored from the scheduler's own WEEKDAYS — kept as a literal here so the checks
174	// layer does not import the scheduler).
175	const SCHEDULE_KEYS = ['dailyHour', 'weeklyDay', 'monthlyDay', 'dispatch', 'agenticTaskInvocationEndpoints', 'endpoints', 'disabledTasks'];
176	
177	// What the endpoint map is called. `endpoints` said nothing about WHICH endpoints —
178	// a scheduler has several kinds it could mean — where these are exactly one thing:
179	// the routine URLs a task's agentic phase is invoked through (#1252). The old
180	// spelling is read while members carry it and written by nothing.
181	export const ENDPOINTS_KEY = 'agenticTaskInvocationEndpoints';
182	// @legacy-tolerance advisory:legacy-shape-in-use retire:#1640
183	export const LEGACY_ENDPOINTS_KEY = 'endpoints';
184	
185	// `taskScheduler.dispatch` chose between the slot scheduler and the work-item
186	// queue while the two coexisted (tasks-dispatch DESIGN §14). The slot scheduler is
187	// deleted (#974), so `queue` is the only mechanism and the key means nothing.
188	//
189	// It stays VALIDATED rather than merely ignored, and `"slots"` is now an error:
190	// a parameter that has stopped being read must fail loudly, because the one thing
191	// a member declaring `"slots"` must not get is the queue running silently under a
192	// declaration that says otherwise. Declaring `"queue"` is still accepted — it says
193	// what is true — and omitting it is the normal shape.
194	export const DISPATCH_MODES = ['queue'];
195	const SCHEDULE_WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
196	
197	// The properties a `packs` entry object may carry: the pack's parameters
198	// (`config`), its adoption-interview answers (`answers` — the owner's verbatim
199	// responses to the questions the pack declares on its pack.mjs, keyed by
200	// question id; read by the adoption skill's interview machinery), and the rule overrides / acceptances that
201	// exist BECAUSE this pack is declared (`rules`, `accept` — they may name any
202	// rule; the entry is their provenance). `via` is written by
203	// resolveDeclaredPacks on materialized dependencies (engine/pack_loader/pack-registry.mjs).
204	// `version` is the pack version this repo has INSTALLED — written by the update
205	// and install flows onto the entry of the pack it describes, which is the only
206	// place it cannot be orphaned from what it prices. It lived in a central
207	// `claudinite.packVersions` map until #1252, where a pack rename left a version
208	// keyed by a spelling no entry carried.
209	export const PACK_ENTRY_KEYS = ['id', 'version', 'config', 'answers', 'rules', 'accept', 'via'];
210	
211	// Load and validate the project's settings. Validity is checked at load — the
212	// moment Claudinite reads the file — and every problem is collected into `errors`
213	// (each `{ what, fix }`), the runner's single settings-validity gate. A wrong
214	// property name, malformed JSON, and a wrong pack name are all equally settings
215	// errors; unknown *pack* names need the registry, so the runner adds those (it
216	// holds the known-pack list). On unparsable/misshaped JSON the usable fields fall
217	// back to empty so the rest of a sweep still runs, with the error reported.
218	//
219	// The returned shape is NORMALIZED: `packs` is plain BARE ids (a local pack's
220	// namespaced `local_packs/<id>` token resolves through packEntryId, so every
221	// downstream lookup — packEntries, the packConfig view — keys by the pack's
222	// own id whichever form the file used), `rules` and `accept` are the top-level
223	// and per-entry settings merged (an entry-sourced acceptance carries
224	// `pack: <id>` as provenance; conflicting severity overrides are a settings
225	// error), and `packConfig` is the per-pack parameter view — each entry's
226	// `config`, overlaid on the legacy top-level key. Checks and env machinery
227	// read this one shape regardless of which form the file used.
228	export function loadConfig(root) {
229	  const path = settingsPath(root);
230	  const name = path.endsWith(LEGACY_SETTINGS_FILE) ? LEGACY_SETTINGS_FILE : SETTINGS_FILE;
231	  const empty = { packs: [], packEntries: [], rules: {}, accept: [], sharedConstants: [], packConfig: {}, taskScheduler: null, engineVersion: null, packVersions: {}, dailyClaudiniteUpdatesRequirePrReview: false, dormant: false, errors: [] };
232	  if (!existsSync(path)) return empty;
233	
234	  let raw;
235	  try {
236	    raw = JSON.parse(readFileSync(path, 'utf8'));
237	  } catch (e) {
238	    return { ...empty, errors: [{ what: `${name} is not valid JSON: ${e.message}`, fix: 'fix the JSON syntax' }] };
239	  }
240	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
241	    return { ...empty, errors: [{ what: `${name} must be a JSON object`, fix: 'wrap the settings in an object: { "packs": [ ... ] }' }] };
242	  }
243	
244	  const errors = [];
245	  for (const key of Object.keys(raw)) {
246	    if (!KNOWN_CONFIG_KEYS.includes(key)) {
247	      errors.push({ what: `unknown setting "${key}"`, fix: `remove it or fix the name — valid settings: ${CONFIG_KEYS.join(', ')}` });
248	    }
249	  }
250	
251	  // --- packs: each entry a pack id or { id, config?, rules?, accept?, via? } ---
252	  const packs = [];
253	  const packEntries = [];
254	  for (const entry of Array.isArray(raw.packs) ? raw.packs : []) {
255	    if (typeof entry === 'string') {
256	      packs.push(packEntryId(entry));
257	      packEntries.push({ id: packEntryId(entry) });
258	      continue;
259	    }
260	    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
261	      errors.push({ what: `packs entry ${JSON.stringify(entry)} is neither a pack id nor an entry object`, fix: 'declare a pack as "name" or { "id": "name", ... }' });
262	      continue;
263	    }
264	    if (typeof entry.id !== 'string') {
265	      errors.push({ what: `packs entry ${JSON.stringify(entry)} has no "id"`, fix: 'give the entry an "id": the pack name' });
266	      continue;
267	    }
268	    for (const key of Object.keys(entry)) {
269	      if (!PACK_ENTRY_KEYS.includes(key)) {
270	        errors.push({ what: `unknown property "${key}" on the "${entry.id}" pack entry`, fix: `remove it or fix the name — valid entry properties: ${PACK_ENTRY_KEYS.join(', ')}` });
271	      }
272	    }
273	    const badShape = (prop, expected) =>
274	      errors.push({ what: `"${prop}" on the "${entry.id}" pack entry must be ${expected}`, fix: `fix or remove the entry's "${prop}"` });
275	    const normalized = { id: packEntryId(entry) };
276	    if (entry.version !== undefined) {
277	      if (isVersion(entry.version)) normalized.version = entry.version;
278	      else badShape('version', 'the installed pack version — date-anchored <day>.<n>');
279	    }
280	    if (entry.config !== undefined) {
281	      if (entry.config !== null && typeof entry.config === 'object' && !Array.isArray(entry.config)) normalized.config = entry.config;
282	      else badShape('config', 'an object of the pack\'s parameters');
283	    }
284	    if (entry.answers !== undefined) {
285	      if (entry.answers !== null && typeof entry.answers === 'object' && !Array.isArray(entry.answers)
286	        && Object.values(entry.answers).every((v) => typeof v === 'string')) normalized.answers = entry.answers;
287	      else badShape('answers', 'an object mapping the pack\'s question ids to string answers');
288	    }
289	    if (entry.rules !== undefined) {
290	      if (entry.rules !== null && typeof entry.rules === 'object' && !Array.isArray(entry.rules)) normalized.rules = entry.rules;
291	      else badShape('rules', 'an object of per-rule severity overrides');
292	    }
293	    if (entry.accept !== undefined) {
294	      if (Array.isArray(entry.accept)) normalized.accept = entry.accept;
295	      else badShape('accept', 'an array of acceptance entries');
296	    }
297	    if (entry.via !== undefined) {
298	      // Written by the declaration resolver on materialized dependencies
299	      // (engine/pack_loader/pack-registry.mjs) — normalized through so readers (the adoption
300	      // interview) can tell a chosen pack from a pulled-in one.
301	      if (Array.isArray(entry.via) && entry.via.every((v) => typeof v === 'string')) normalized.via = entry.via;
302	      else badShape('via', 'an array of pack ids (the declaration resolver writes it)');
303	    }
304	    packs.push(normalized.id);
305	    packEntries.push(normalized);
306	  }
307	
308	  // --- rules: top-level and per-entry merged; a conflict is a settings error,
309	  // never a silent last-writer-wins — two packs (or a pack and the top level)
310	  // disagreeing about a rule's severity is a decision the project must make.
311	  const rules = {};
312	  const ruleSource = {};
313	  const mergeRules = (overrides, source) => {
314	    for (const [ruleId, severity] of Object.entries(overrides)) {
315	      if (ruleId in rules && rules[ruleId] !== severity) {
316	        errors.push({
317	          what: `rule "${ruleId}" is set to "${rules[ruleId]}" by ${ruleSource[ruleId]} and "${severity}" by ${source}`,
318	          fix: 'make the overrides agree, or keep the rule on one of them',
319	        });
320	        continue;
321	      }
322	      rules[ruleId] = severity;
323	      ruleSource[ruleId] = source;
324	    }
325	  };
326	  if (raw.rules && typeof raw.rules === 'object') mergeRules(raw.rules, 'the top-level "rules"');
327	  for (const entry of packEntries) {
328	    if (entry.rules) mergeRules(entry.rules, `the "${entry.id}" pack entry`);
329	  }
330	
331	  // --- accept: top-level entries, then each pack entry's stamped with its
332	  // provenance (`pack: <id>` — which declaration motivated the exemption).
333	  const accept = Array.isArray(raw.accept) ? [...raw.accept] : [];
334	  for (const entry of packEntries) {
335	    for (const a of entry.accept ?? []) accept.push({ ...a, pack: entry.id });
336	  }
337	
338	  // --- packConfig view: per-pack parameters — e.g. the dirs a repo's
339	  // package.json lives in for the node pack's env install. Entry `config` is
340	  // the home; the legacy top-level key stays readable underneath it.
341	  const packConfig = raw.packConfig && typeof raw.packConfig === 'object' && !Array.isArray(raw.packConfig) ? { ...raw.packConfig } : {};
342	  for (const entry of packEntries) {
343	    if (entry.config !== undefined) packConfig[entry.id] = entry.config;
344	  }
345	
346	  // --- taskScheduler: the per-repo maintenance anchor (UTC). Range-validated at
347	  // load so a bad anchor is a settings error like any other; absence is legal
348	  // (the scheduler fills the documented defaults). The value passes through
349	  // unchanged for the scheduler to normalize.
350	  let taskScheduler = null;
351	  if (raw.taskScheduler !== undefined) {
352	    if (raw.taskScheduler === null || typeof raw.taskScheduler !== 'object' || Array.isArray(raw.taskScheduler)) {
353	      errors.push({ what: '"taskScheduler" must be an object', fix: 'e.g. { "dailyHour": 4, "weeklyDay": "Sun", "monthlyDay": 1 }' });
354	    } else {
355	      for (const key of Object.keys(raw.taskScheduler)) {
356	        if (!SCHEDULE_KEYS.includes(key)) {
357	          errors.push({ what: `unknown "taskScheduler" setting "${key}"`, fix: `remove it or fix the name — valid taskScheduler settings: ${SCHEDULE_KEYS.join(', ')}` });
358	        }
359	      }
360	      const { dailyHour, weeklyDay, monthlyDay } = raw.taskScheduler;
361	      if (dailyHour !== undefined && !(Number.isInteger(dailyHour) && dailyHour >= 0 && dailyHour <= 23)) {
362	        errors.push({ what: `"taskScheduler.dailyHour" must be an integer 0–23 (UTC), got ${JSON.stringify(dailyHour)}`, fix: 'set an hour of the day, 0 through 23' });
363	      }
364	      if (weeklyDay !== undefined && !SCHEDULE_WEEKDAYS.includes(weeklyDay)) {
365	        errors.push({ what: `"taskScheduler.weeklyDay" must be one of ${SCHEDULE_WEEKDAYS.join(', ')}, got ${JSON.stringify(weeklyDay)}`, fix: 'name a weekday, e.g. "Sun"' });
366	      }
367	      if (monthlyDay !== undefined && !(Number.isInteger(monthlyDay) && monthlyDay >= 1 && monthlyDay <= 31)) {
368	        errors.push({ what: `"taskScheduler.monthlyDay" must be an integer 1–31, got ${JSON.stringify(monthlyDay)}`, fix: 'set a day of the month, 1 through 31 (clamped to the month length)' });
369	      }
370	      // The tasks this repo does not want instantiated (task-preconditions DESIGN,
371	      // "What is not a precondition"). Repo shape — "this repo ships the store
372	      // pipeline", "this repo has a vendored mount" — is a fact adoption settled,
373	      // so it is answered once here rather than re-asked by a precondition every
374	      // night. Validated as a shape only: whether the named task exists is a
375	      // question about the repo's declared packs, answered where tasks are
376	      // discovered, and a member may legitimately disable a task it has not
377	      // adopted yet.
378	      const { disabledTasks } = raw.taskScheduler;
379	      if (disabledTasks !== undefined
380	          && !(Array.isArray(disabledTasks)
381	            && disabledTasks.every((id) => typeof id === 'string' && /^[^/\s]+\/[^/\s]+$/.test(id)))) {
382	        errors.push({
383	          what: `"taskScheduler.disabledTasks" must be an array of "<pack>/<task>" ids, got ${JSON.stringify(disabledTasks)}`,
384	          fix: 'list the tasks this repo does not run, e.g. ["claudinite-lifecycle/update"]',
385	        });
386	      }
387	
388	      const { dispatch } = raw.taskScheduler;
389	      const endpoints = raw.taskScheduler[ENDPOINTS_KEY] ?? raw.taskScheduler[LEGACY_ENDPOINTS_KEY];
390	      if (dispatch !== undefined && !DISPATCH_MODES.includes(dispatch)) {
391	        errors.push({
392	          what: `"taskScheduler.dispatch" must be one of ${DISPATCH_MODES.join(', ')}, got ${JSON.stringify(dispatch)}`,
393	          fix: 'omit the key — the work-item queue is the only dispatch mechanism; "slots" named the slot scheduler, which is deleted',
394	        });
395	      }
396	      // The endpoint map (tasks-dispatch DESIGN §12): a name → { url, tokenSecret }.
397	      // `tokenSecret` is the NAME of a repo Actions secret and never a value —
398	      // that indirection is the whole reason a task may declare an endpoint at all,
399	      // since a task declaration is vendored verbatim into every consuming repo.
400	      if (endpoints !== undefined) {
401	        if (endpoints === null || typeof endpoints !== 'object' || Array.isArray(endpoints)) {
402	          errors.push({ what: `"taskScheduler.${ENDPOINTS_KEY}" must be an object of endpoint name → { url, tokenSecret }`, fix: 'e.g. { "default": { "url": "https://…", "tokenSecret": "CCR_SESSION_TOKEN" } }' });
403	        } else {
404	          for (const [epName, entry] of Object.entries(endpoints)) {
405	            if (entry === null || typeof entry !== 'object' || Array.isArray(entry)
406	                || typeof entry.url !== 'string' || typeof entry.tokenSecret !== 'string') {
407	              errors.push({ what: `"taskScheduler.${ENDPOINTS_KEY}.${epName}" must be { url, tokenSecret } (both strings)`, fix: 'give the endpoint an invocation URL and the NAME of the repo Actions secret holding its token — never the token itself' });
408	            }
409	          }
410	        }
411	      }
412	      taskScheduler = raw.taskScheduler;
413	    }
414	  }
415	
416	  // --- the installed mount: the engine version this repo holds, and the version of
417	  // each pack it has installed. The current home is the top-level `engineVersion`
418	  // and each pack entry's own `version`; the retired `claudinite` block is read
419	  // underneath for a member the #1252 record has not reached, and a pack renamed
420	  // since that block was written still keys its version under the old spelling, so
421	  // the legacy map is canonicalized before anything compares it.
422	  let engineVersion = null;
423	  if (raw.engineVersion !== undefined) {
424	    if (isVersion(raw.engineVersion)) engineVersion = raw.engineVersion;
425	    else {
426	      errors.push({
427	        what: `"engineVersion" must be a version — date-anchored <day>.<n>, got ${JSON.stringify(raw.engineVersion)}`,
428	        fix: 'leave it to the update flows, which write the version they installed',
429	      });
430	    }
431	  } else if (isVersion(raw.claudinite?.engineVersion)) {
432	    engineVersion = raw.claudinite.engineVersion;
433	  }
434	
435	  const packVersions = {};
436	  const legacyVersions = raw.claudinite?.packVersions;
437	  if (legacyVersions && typeof legacyVersions === 'object' && !Array.isArray(legacyVersions)) {
438	    Object.assign(packVersions, canonicalPackVersions(legacyVersions));
439	  }
440	  for (const entry of packEntries) {
441	    if (entry.version !== undefined) packVersions[entry.id] = entry.version;
442	  }
443	
444	  // --- the delivery override. `true` is the only value that means anything, so
445	  // anything else present is a typo the run must not read as "yes" or silently as
446	  // "no" — a wrong answer here is a PR merged unreviewed on a repo that asked for
447	  // review, or a repo's daily update stalled forever waiting for a human nobody
448	  // told. The retired `maintenance.delivery` says the same thing the old way, and
449	  // an unrecognised value THERE is equally an error rather than a default.
450	  let requirePrReview = false;
451	  if (raw.dailyClaudiniteUpdatesRequirePrReview !== undefined) {
452	    if (typeof raw.dailyClaudiniteUpdatesRequirePrReview === 'boolean') {
453	      requirePrReview = raw.dailyClaudiniteUpdatesRequirePrReview;
454	    } else {
455	      errors.push({
456	        what: `"dailyClaudiniteUpdatesRequirePrReview" must be true or false, got ${JSON.stringify(raw.dailyClaudiniteUpdatesRequirePrReview)}`,
457	        fix: 'set it to true to leave this repo\'s update PR for a human, or remove the key',
458	      });
459	    }
460	  } else if (raw.maintenance?.delivery !== undefined) {
461	    const legacy = String(raw.maintenance.delivery).trim();
462	    if (['review', 'pr'].includes(legacy)) requirePrReview = true;
463	    else if (!['auto-merge', 'auto', 'push', ''].includes(legacy)) {
464	      errors.push({
465	        what: `the retired "maintenance.delivery" holds ${JSON.stringify(raw.maintenance.delivery)}, which is neither auto-merge nor review`,
466	        fix: 'remove the "maintenance" block — set "dailyClaudiniteUpdatesRequirePrReview": true if this repo\'s update PR must wait for a human',
467	      });
468	    }
469	  }
470	
471	  // --- dormant: a plain boolean, validated as one. A string "true", a `{ since }`
472	  // object or a reason left in its place would all read as dormant to a truthiness
473	  // test and as active to this one, and the difference is a whole repo's scheduled
474	  // work — so the wrong TYPE is a settings error, not a value to coerce.
475	  if (raw.dormant !== undefined && typeof raw.dormant !== 'boolean') {
476	    errors.push({
477	      what: `"dormant" must be true or false, got ${JSON.stringify(raw.dormant)}`,
478	      fix: 'set "dormant": true to stop this project\'s recurring work, or remove the key',
479	    });
480	  }
481	
482	  return {
483	    packs,
484	    packEntries,
485	    rules,
486	    accept,
487	    sharedConstants: Array.isArray(raw.sharedConstants) ? raw.sharedConstants : [],
488	    packConfig,
489	    taskScheduler,
490	    // The installed mount, normalized from wherever this member happens to spell
491	    // it: the top-level `engineVersion` and each entry's own `version`, falling
492	    // back to the retired `claudinite` block for a member that has not run the
493	    // #1252 record yet. Downstream reads ONE shape and never learns there were
494	    // two — and omitting a declared key from this returned shape is the worst
495	    // kind of bug, legal to write and impossible to read: it is what made the
496	    // stamp invisible to the scheduler and silently killed baselining fleet-wide,
497	    // every repo self-skipping as "no vendored mount" while its runs went green.
498	    // The CONFIG_KEYS-survive-loadConfig test pins the whole set.
499	    engineVersion,
500	    packVersions,
501	    // The harsh override, normalized to the boolean every caller asks for and named
502	    // exactly as the file names it — one spelling, so nothing has to learn that the
503	    // key and the field it loads into are different words. Absent is the normal
504	    // shape and means the update PR lands on its own; the retired
505	    // `maintenance.delivery: review` says the same thing the old way.
506	    dailyClaudiniteUpdatesRequirePrReview: requirePrReview,
507	    // Normalized to a boolean rather than passed through: everything downstream
508	    // asks "is this project dormant", and a tri-state (true / false / absent) would
509	    // invite each caller to answer the absent case for itself. Absent is active.
510	    dormant: isDormant(raw),
511	    errors,
512	  };
513	}
514	
515	export function buildContext({ root, mode = 'changed', baseOverride = null, transcriptPath = null }) {
516	  root = resolve(root);
517	  const baseRef = baseOverride || resolveBaseRef(root);
518	  refreshBaseRef(root, baseRef);
519	  const mergeBase = baseRef ? (gitTry(root, 'merge-base', 'HEAD', baseRef) || '').trim() || null : null;
520	  // Diffing against HEAD keeps uncommitted work in scope even when no base branch resolves.
521	  const diffBase = mergeBase || 'HEAD';
522	  // Is this commit already on the base branch? `--is-ancestor` exits non-zero for "no",
523	  // which gitTry surfaces as null. No base ref to compare against ⇒ nothing is known to
524	  // be on it, so nothing is filtered out.
525	  const onBaseBranch = (sha) =>
526	    !!baseRef && gitTry(root, 'merge-base', '--is-ancestor', sha, baseRef) !== null;
527	
528	  const tracked = lines(gitTry(root, 'ls-files'));
529	  const untracked = lines(gitTry(root, 'ls-files', '--others', '--exclude-standard'));
530	
531	  const vsBase = lines(gitTry(root, 'diff', '--name-only', '--diff-filter=d', diffBase));
532	  let scanned;
533	  if (mode === 'all') {
534	    scanned = [...tracked, ...untracked];
535	  } else {
536	    scanned = [...new Set([...vsBase, ...untracked])];
537	  }
538	  // The vendored corpus under the shared mount is canon-owned, never the
539	  // project's own code — structurally out of scope for every check, on any git
540	  // host and any checkout (deliberately not attribute-driven). The consumer's
541	  // own .claudinite/local/packs/ sits BESIDE the shared mount and stays fully
542	  // in scope.
543	  // git emits '/'-separated paths on every platform; SHARED_SUBDIR is joined
544	  // with the platform separator, so normalize before prefix-matching.
545	  const sharedPrefix = `${SHARED_SUBDIR.split(sep).join('/')}/`;
546	  scanned = scanned.filter((f) => !f.startsWith(sharedPrefix));
547	  // Every in-scope regular file, vendored/generated included.
548	  const allFiles = scanned.filter((f) => existsSync(join(root, f)) && statSync(join(root, f)).isFile());
549	  // The default sweep excludes vendored/generated files, so `ctx.files` is the
550	  // project's OWN authored code and every check skips them for free (see vendoredSet).
551	  const vendored = vendoredSet(root, allFiles);
552	  const files = allFiles.filter((f) => !vendored.has(f));
553	  // The in-scope files the current change touched (vs the scoping base),
554	  // untracked included — the file set behind lines.mjs addedLines, for
555	  // check-the-work rules that judge the work rather than re-audit the world.
556	  const changedSet = new Set([...vsBase, ...untracked]);
557	  const changedFiles = files.filter((f) => changedSet.has(f));
558	
559	  const deleted = mergeBase ? lines(gitTry(root, 'diff', '--name-only', '--diff-filter=D', mergeBase)) : [];
560	
561	  let commits = [];
562	  if (mergeBase) {
563	    const out = gitTry(root, 'log', '--format=%s%n%b%x00', `${mergeBase}..HEAD`);
564	    commits = (out || '').split('\0').map((m) => m.trim()).filter(Boolean);
565	  }
566	
567	  const branch = (gitTry(root, 'rev-parse', '--abbrev-ref', 'HEAD') || '').trim();
568	
569	  // Conversation surface: the Stop hook forwards the session's transcript_path;
570	  // every other surface (CI, a manual run) has none, and conversation rules must
571	  // return [] when this is null. Parsed lazily and cached — most sweeps never ask.
572	  let conversationCache;
573	  let sessionEntriesCache;
574	
575	  // Checks are read-only over an immutable snapshot of the tree, so file and
576	  // base-blob reads are cached for the sweep: many rules re-read the same files,
577	  // and each readBase is otherwise a git subprocess.
578	  const readCache = new Map();
579	  const readBaseCache = new Map();
580	
581	  return {
582	    root,
583	    mode,
584	    baseRef,
585	    mergeBase,
586	    files,
587	    allFiles,
588	    changedFiles,
589	    tracked,
590	    untracked,
591	    deleted,
592	    commits,
593	    branch,
594	    config: loadConfig(root),
595	
596	    exists: (path) => existsSync(join(root, path)),
597	    read(path) {
598	      if (!readCache.has(path)) {
599	        let text;
600	        try { text = readFileSync(join(root, path), 'utf8'); } catch { text = null; }
601	        readCache.set(path, text);
602	      }
603	      return readCache.get(path);
604	    },
605	
606	    // File content at the scoping base (the merge-base with the base branch), or
607	    // null if the file didn't exist there or no base resolves. Lets a delta
608	    // check compare structured state — e.g. a manifest's permission set — against
609	    // the baseline precisely, immune to text-diff line noise (JSON trailing
610	    // commas make appending an array element re-touch the previous line).
611	    readBase(path) {
612	      if (!mergeBase) return null;
613	      if (!readBaseCache.has(path)) readBaseCache.set(path, gitTry(root, 'show', `${mergeBase}:${path}`));
614	      return readBaseCache.get(path);
615	    },
616	
617	    // Added lines of one file relative to the scoping base (untracked file = every line).
618	    addedLines(file) {
619	      if (!tracked.includes(file)) {
620	        const text = this.read(file);
621	        return text === null ? [] : text.split('\n').map((t, i) => ({ line: i + 1, text: t }));
622	      }
623	      const out = gitTry(root, 'diff', '-U0', diffBase, '--', file);
624	      const added = [];
625	      let lineNo = 0;
626	      for (const l of (out || '').split('\n')) {
627	        const hunk = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(l);
628	        if (hunk) { lineNo = Number(hunk[1]); continue; }
629	        if (l.startsWith('+') && !l.startsWith('+++')) { added.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
630	        else if (!l.startsWith('-')) lineNo += l ? 1 : 0;
631	      }
632	      return added;
633	    },
634	
635	    // The lines the change REMOVES from a tracked file, numbered as the base
636	    // had them — the diff's "-" side, the mirror of addedLines. A file the
637	    // base did not hold removed nothing.
638	    removedLines(file) {
639	      if (!mergeBase || !tracked.includes(file)) return [];
640	      const out = gitTry(root, 'diff', '-U0', diffBase, '--', file);
641	      const removed = [];
642	      let lineNo = 0;
643	      for (const l of (out || '').split('\n')) {
644	        const hunk = /^@@ -(\d+)(?:,\d+)? \+\d+(?:,\d+)? @@/.exec(l);
645	        if (hunk) { lineNo = Number(hunk[1]); continue; }
646	        if (l.startsWith('-') && !l.startsWith('---')) { removed.push({ line: lineNo, text: l.slice(1) }); lineNo += 1; }
647	        else if (!l.startsWith('+')) lineNo += l ? 1 : 0;
648	      }
649	      return removed;
650	    },
651	
652	    // Parsed transcript entries of the session driving this run, or null when no
653	    // transcript is available (see conversationCache above).
654	    conversation() {
655	      if (conversationCache !== undefined) return conversationCache;
656	      if (!transcriptPath || !existsSync(transcriptPath)) return (conversationCache = null);
657	      try { conversationCache = parseEntries(readFileSync(transcriptPath, 'utf8')); }
658	      catch { conversationCache = null; }
659	      return conversationCache;
660	    },
661	
662	    // Every entry the session wrote — the transcript above plus each subagent
663	    // stream beside it — for the rules that judge what the session DID: the
664	    // skills it loaded, the calls it made. `conversation()` stays the session
665	    // file alone, since that is where the owner's turns are. Empty on a surface
666	    // with no transcript, which `conversation()` is what distinguishes from a
667	    // session that did nothing.
668	    sessionEntries() {
669	      if (sessionEntriesCache === undefined) {
670	        sessionEntriesCache = sessionTranscriptPaths(transcriptPath).flatMap((path) => {
671	          // A stream unreadable mid-write costs its own entries, never the others'.
672	          try { return parseEntries(readFileSync(path, 'utf8')); } catch { return []; }
673	        });
674	      }
675	      return sessionEntriesCache;
676	    },
677	
678	    // The branch's own commits since the merge-base, oldest first, each with its
679	    // changed files and committer date — for rules about the ORDER work landed in
680	    // (ctx.commits keeps only messages). Merges excluded: their file list is
681	    // empty under --name-only and their content arrives via their parents.
682	    commitsWithFiles() {
683	      if (!mergeBase) return [];
684	      const out = gitTry(root, 'log', '--reverse', '--no-merges', '--name-only',
685	        '--format=%x00%H%x1f%cI%x1f%s', `${mergeBase}..HEAD`);
686	      const commits = [];
687	      for (const block of (out || '').split('\0')) {
688	        if (!block.trim()) continue;
689	        const [head, ...rest] = block.trim().split('\n');
690	        const [sha, date, subject] = head.split('\x1f');
691	        commits.push({ sha, date, subject, files: rest.map((f) => f.trim()).filter(Boolean) });
692	      }
693	      return commits;
694	    },
695	
696	    // Merge commits the current change introduces — those on HEAD's first-parent
697	    // chain since the merge-base with the base branch (the squash-only effect
698	    // check, scoped to the work). Empty when no base resolves or the branch is
699	    // even with it; pre-existing merges already on the base are out of range.
700	    //
701	    // The range alone trusts the merge-base to be right, and it isn't always: a
702	    // shallow clone's grafted boundary or a criss-cross history can hand back a
703	    // merge-base that sweeps the base branch's own merges into the range. So each
704	    // candidate is confirmed against the base ref itself — a merge already on the
705	    // base branch was never introduced here, whatever the range says. Offline and
706	    // exact, and it holds when refreshBaseRef couldn't run.
707	    introducedMergeCommits() {
708	      if (!mergeBase) return [];
709	      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase}..HEAD`);
710	      return lines(out).map((l) => {
711	        const i = l.indexOf(' ');
712	        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
713	      }).filter(({ sha }) => !onBaseBranch(sha));
714	    },
715	
716	    // Fixed-string search across tracked files; git grep exits 1 on no match.
717	    // The vendored shared mount is structurally out of the sweep (canon-owned,
718	    // never the project's own code — vendoring/DESIGN.md item 6), so it is
719	    // excluded here exactly as it is from the scanned file set above: a hit
720	    // inside it must never become a finding.
721	    grepTracked(needle) {
722	      const out = gitTry(root, 'grep', '-n', '-F', needle, '--', '.', `:(exclude)${sharedPrefix}`);
723	      return lines(out).map((l) => {
724	        const m = /^([^:]+):(\d+):(.*)$/.exec(l);
725	        return m ? { file: m[1], line: Number(m[2]), text: m[3] } : null;
726	      }).filter(Boolean);
727	    },
728	  };
729	}
730	
731	export const pathDepth = (p) => (p === '.' || p === '' ? [] : p.split(sep));
