246	// coverage half on the way in: an already-open issue gets a comment ONLY when the state
247	// actually changed, because a sweep over a fleet that is slow to heal would otherwise
248	// turn every thread into a wall of identical notes. That restraint is what lets this
249	// half ride the daily cadence rather than the weekly one it used to have.
250	export async function convergeDrift(gh, home, { unhealthy, healthySet, goneSet, dormantSet = new Set() }) {
251	  const actions = [];
252	  const { open: openIssues, closed } = await labeledIssues(gh, home, LABEL);
253	  const open = new Map(openIssues.map((i) => [i.title, i]));
254	  const wanted = new Map(unhealthy.map((u) => [u.fullName, u]));
255	
256	  for (const [fullName, verdict] of wanted) {
257	    const title = driftTitle(fullName);
258	    const existing = open.get(title);
259	    if (existing) {
260	      const was = MARKER_RE.exec(existing.body ?? '')?.[1];
261	      if (was === verdict.state) continue; // same story as yesterday — say nothing
262	      await gh(`/repos/${home}/issues/${existing.number}`, {
263	        method: 'PATCH', body: { body: driftBody(fullName, verdict) },
264	      });
265	      await gh(`/repos/${home}/issues/${existing.number}/comments`, {
266	        method: 'POST', body: { body: `The sweep's verdict changed: \`${was ?? 'unrecorded'}\` → \`${verdict.state}\`. ${verdict.detail}.` },
267	      });
268	      actions.push(`updated #${existing.number} (${fullName}: ${was ?? 'unrecorded'} → ${verdict.state})`);
269	      continue;
270	    }
271	    const prior = closed.filter((i) => i.title === title)
272	      .sort((a, b) => new Date(b.closed_at) - new Date(a.closed_at))[0];
273	    if (prior && prior.state_reason === 'not_planned') continue; // closed as out-of-fleet; re-adding it is the standing fix
274	    if (prior) {
275	      await gh(`/repos/${home}/issues/${prior.number}`, {
276	        method: 'PATCH', body: { state: 'open', body: driftBody(fullName, verdict) },
277	      });
278	      await gh(`/repos/${home}/issues/${prior.number}/comments`, {
279	        method: 'POST', body: { body: `Reopened by the sweep: \`${fullName}\` has fallen behind again (${verdict.state}). ${verdict.detail}.` },
280	      });
281	      actions.push(`reopened #${prior.number} (${fullName}: ${verdict.state})`);
282	    } else {
283	      const { status, json } = await gh(`/repos/${home}/issues`, {
284	        method: 'POST',
285	        body: { title, body: driftBody(fullName, verdict), labels: [LABEL] },
286	      });
287	      if (status !== 201) throw new Error(`creating drift issue for ${fullName} returned ${status}`);
288	      actions.push(`opened #${json.number} (${fullName}: ${verdict.state})`);
289	    }
290	  }
291	
292	  for (const [title, issue] of open) {
293	    const m = TITLE_RE.exec(title);
294	    if (!m) continue;
295	    const fullName = m[1].toLowerCase();
296	    if (wanted.has(fullName)) continue;
297	    let reason = null; let note = null;
298	    if (healthySet.has(fullName)) {
299	      reason = 'completed'; note = 'is up to date with canon again';
300	    } else if (dormantSet.has(fullName)) {
301	      // `not planned`, not `completed`: the drift was never fixed, the repo was
302	      // taken out of the race. Closing it `completed` would claim a repair nobody
303	      // made, and leaving it open would be the nagging dormancy exists to stop.
304	      reason = 'not_planned'; note = 'has declared itself dormant — it is out of the recurring work, so the sweep no longer measures it';
305	    } else if (goneSet.has(fullName)) {
306	      reason = 'not_planned'; note = 'is no longer a covered member of the fleet (excluded, deleted, archived, or uncovered)';
307	    }
308	    if (!reason) continue; // classified UNKNOWN this run — say nothing rather than guess
309	    await gh(`/repos/${home}/issues/${issue.number}/comments`, {
310	      method: 'POST', body: { body: `Closed by the sweep: \`${m[1]}\` ${note}.` },
311	    });
312	    await gh(`/repos/${home}/issues/${issue.number}`, {
313	      method: 'PATCH', body: { state: 'closed', state_reason: reason },
314	    });
315	    actions.push(`closed #${issue.number} (${m[1]}: ${note})`);
316	  }
317	  return actions;
318	}
319	
320	// --- the freshness section of the report (pure) -------------------------------
321	
322	// Enumerates the FULL fleet: every repo lands in exactly one list — fresh (with how
323	// fresh), unhealthy (with its root cause), dormant, out of scope (with why), unknown —
