1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import {
4	  buildRoster, coverageView, freshnessView,
5	} from '../../../tasks/fleet-roster/check-fleet-roster.mjs';
6	import { canonVersions } from '../../../tasks/fleet-roster/drift-issues.mjs';
7	
8	// The merged walk (#788). What is worth locking down is not that the two questions
9	// still get answered — their own modules' tests cover that — but that the walk reads
10	// each repo ONCE and that the two views can still disagree about what it found. The
11	// disagreements below are the ones the two separate sweeps used to reach by accident;
12	// here they are deliberate, and a test says so.
13	
14	const HOME = 'o/enforcer';
15	const CANON = 'o/Claudinite';
16	
17	const CANON_SOURCE = {
18	  'engine/version.mjs': 'export const ENGINE_VERSION = 4;\n',
19	  'packs/basics/pack.mjs': "export default {\n  id: 'basics',\n  version: 7,\n};\n",
20	};
21	
22	const repo = (name, over = {}) => ({ name, full_name: `o/${name}`, archived: false, fork: false, ...over });
23	
24	// A fake API over declarations, scheduler-workflow presence and canon's own version
25	// numbers. Records every path so "read once" is an assertion rather than a claim.
26	//
27	// It serves the CURRENT settings-file name only: every member here has run the
28	// rename record, and a read of the retired name 404s exactly as it would in the
29	// fleet. `legacyDeclarations` is the other side, for the members that have not.
30	function fakeGh({ declarations = {}, legacyDeclarations = {}, schedulers = [], errors = {} } = {}) {
31	  const seen = [];
32	  const gh = async (path) => {
33	    seen.push(path);
34	    if (errors[path]) return { status: errors[path], json: null };
35	
36	    const served = (decl) => ({ status: 200, json: { content: Buffer.from(typeof decl === 'string' ? decl : JSON.stringify(decl)).toString('base64'), sha: 'sha' } });
37	    let m = /^\/repos\/(.+)\/contents\/\.claudinite-settings\.json$/.exec(path);
38	    if (m) return declarations[m[1]] === undefined ? { status: 404, json: null } : served(declarations[m[1]]);
39	    m = /^\/repos\/(.+)\/contents\/\.claudinite-checks\.json$/.exec(path);
40	    if (m) return legacyDeclarations[m[1]] === undefined ? { status: 404, json: null } : served(legacyDeclarations[m[1]]);
41	
42	    m = /^\/repos\/(.+)\/contents\/\.github\/workflows\/claudinite-scheduler\.yml$/.exec(path);
43	    if (m) return { status: schedulers.includes(m[1]) ? 200 : 404, json: { content: '' } };
